const CSS = `
.ml-root{--gold:#e0c28c;--bronze:#c19a63;--text:#f5f3ee;--muted:#b8bbbd;--line:#c19a6359;--green:#9cddb5;--red:#ffaaa7;box-sizing:border-box;width:100%;height:100dvh;display:grid;grid-template-rows:auto minmax(0,1fr) auto;gap:clamp(6px,1vh,10px);padding:clamp(6px,1.4vh,15px);overflow:hidden;background:radial-gradient(circle at 8% 10%,#9f713026,transparent 38%),radial-gradient(circle at 90% 90%,#a8793229,transparent 34%),#0d1114;color:var(--text);font-family:Geist,system-ui,sans-serif}
.ml-root *{box-sizing:border-box}.ml-root button{font:inherit;cursor:pointer}.ml-root button:focus-visible{outline:2px solid var(--gold);outline-offset:2px}.ml-root button:disabled{cursor:not-allowed;opacity:.45}.ml-root h1,.ml-root h2,.ml-root p{margin:0}
.ml-head,.ml-body{border:1px solid #d8b67866;border-radius:17px;background:linear-gradient(135deg,#30343bd9,#1b1f23ed 57%,#24282de8);box-shadow:0 18px 42px #0006,inset 0 1px #ffffff12}
.ml-head,.ml-foot{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:8px clamp(10px,2vw,20px)}.ml-head{min-height:53px}.ml-foot{min-height:54px;border-top:1px solid var(--line)}
.ml-eyebrow,.ml-kick{color:var(--gold);font-size:12px;font-weight:800;letter-spacing:.08em;text-transform:uppercase}.ml-progress{display:flex;gap:4px;max-width:60%;overflow:hidden}.ml-progress i{flex:none;width:11px;height:4px;border-radius:5px;background:#4a4d50}.ml-progress i.on{background:var(--gold)}
.ml-body{min-height:0;overflow:auto;padding:clamp(12px,2.8vh,28px);display:flex;align-items:center;justify-content:center;scrollbar-color:#c19a63 #1b1f23}.ml-slide{width:100%;max-width:980px;margin:auto;display:grid;gap:clamp(9px,1.6vh,16px);animation:ml-enter .55s cubic-bezier(.2,.8,.2,1) both;perspective:1000px}
@keyframes ml-enter{from{opacity:0;transform:translate3d(24px,0,-75px) rotateY(7deg)}to{opacity:1;transform:none}}
.ml-title{font-size:clamp(24px,3vw,38px);line-height:1.08;letter-spacing:-.025em;color:var(--gold)}.ml-sub{font-size:clamp(13px,1.45vw,17px);line-height:1.45;color:var(--muted)}.ml-lead{font-size:clamp(16px,1.9vw,22px);line-height:1.3;font-weight:650}.ml-dim{color:var(--muted);font-size:12px}.ml-strong{color:var(--gold);font-weight:700}
.ml-card-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.ml-card-grid.cols3{grid-template-columns:repeat(3,minmax(0,1fr))}.ml-card{border:1px solid var(--line);border-radius:12px;background:#ffffff0b;padding:12px;min-height:72px;box-shadow:0 7px 17px #0003;animation:ml-build .55s cubic-bezier(.18,.8,.2,1) both;animation-delay:var(--delay);overflow-wrap:anywhere}.ml-card b{color:var(--gold)}.ml-card p{line-height:1.35}.ml-card small{color:var(--muted);line-height:1.3}.ml-card button{width:100%;text-align:left}.ml-card.reveal{cursor:pointer;transform-style:preserve-3d;transition:border-color .25s,background .25s,transform .35s}.ml-card.reveal:hover{border-color:var(--gold);transform:translateY(-2px) translateZ(14px)}.ml-card.reveal.open{border-color:#d8b678;background:#c19a6326}.ml-card .hint{color:var(--gold);font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.08em;margin-bottom:4px}.ml-card .hidden-copy{color:var(--muted);font-size:13px}.ml-card.reveal.open .hidden-copy{color:var(--text)}
@keyframes ml-build{from{opacity:0;transform:translate3d(-20px,14px,-70px) rotateY(-17deg)}to{opacity:1;transform:none}}
.ml-chat{display:grid;gap:7px}.ml-bubble{max-width:83%;padding:8px 11px;border:1px solid var(--line);border-radius:13px;background:#ffffff0b;animation:ml-pop .45s ease both;animation-delay:var(--delay)}.ml-bubble.right{justify-self:end;border-color:#c19a6377;background:#c19a6324}.ml-bubble small{display:block;color:var(--gold);font-size:11px;font-weight:800;text-transform:uppercase}.ml-bubble p{font-size:clamp(13px,1.45vw,16px);font-weight:600;line-height:1.3}@keyframes ml-pop{from{opacity:0;transform:rotateX(-45deg) translateY(9px)}to{opacity:1;transform:none}}
.ml-option{width:100%;min-height:47px;display:flex;align-items:center;gap:10px;padding:9px 12px;border:1px solid var(--line);border-radius:11px;background:#ffffff0b;color:var(--text);text-align:left;transition:transform .2s,border-color .2s,background .2s}.ml-option:hover:not(:disabled){transform:translateY(-2px);border-color:var(--gold)}.ml-option i{flex:none;display:grid;place-items:center;width:25px;height:25px;border:1px solid var(--line);border-radius:50%;color:var(--gold);font-style:normal;font-size:12px;font-weight:800}.ml-option.good{border-color:#68ab7e;background:#25593a55}.ml-option.bad{border-color:#d77a79;background:#6a282858}.ml-options{display:grid;gap:7px}.ml-feedback{min-height:25px;padding:8px 10px;border:1px solid var(--line);border-radius:9px;background:#c19a631f;color:var(--gold);font-size:13px;line-height:1.35}.ml-feedback.good{border-color:#68ab7e;background:#25593a55;color:var(--green)}.ml-feedback.bad{border-color:#d77a79;background:#6a282858;color:var(--red)}
.ml-button{min-height:44px;padding:9px 17px;border:1px solid var(--line);border-radius:11px;background:#ffffff0b;color:var(--text);font-weight:700}.ml-button.primary{border-color:#d8b678;background:linear-gradient(110deg,#f0d39a,#c5985f);color:#17191a}.ml-button:hover:not(:disabled){border-color:var(--gold)}.ml-button.primary:hover:not(:disabled){background:#f4dcae}.ml-actions{display:flex;align-items:center;justify-content:space-between;gap:8px}.ml-note{font-size:12px;color:var(--muted)}
.ml-token-wrap{display:flex;flex-wrap:wrap;gap:7px;padding:10px;border:1px dashed var(--line);border-radius:12px;min-height:60px}.ml-token{min-height:41px;padding:6px 10px;border:1px solid var(--bronze);border-radius:9px;background:#ffffff14;color:var(--text);font-weight:650;transition:transform .2s}.ml-token:hover:not(:disabled){transform:translateY(-3px)}.ml-answer{font-size:clamp(15px,1.8vw,20px);color:var(--gold);font-weight:650}.ml-vocab-card{min-height:92px;perspective:800px;border:0;background:none;padding:0;color:var(--text);text-align:left}.ml-vocab-inner{display:block;position:relative;min-height:92px;transform-style:preserve-3d;transition:transform .6s}.ml-vocab-card.open .ml-vocab-inner{transform:rotateY(180deg)}.ml-vocab-face{position:absolute;inset:0;display:grid;align-content:center;gap:3px;padding:10px;border:1px solid var(--line);border-radius:10px;background:#292e33;backface-visibility:hidden;-webkit-backface-visibility:hidden}.ml-vocab-face.back{transform:rotateY(180deg);border-color:var(--gold);background:#42382a}.ml-vocab-face strong{font-size:clamp(13px,1.5vw,18px)}.ml-vocab-face small{color:var(--muted);font-size:11px;line-height:1.2}.ml-vocab-face .hint{color:var(--gold);font-size:10px;text-transform:uppercase;letter-spacing:.08em}
.ml-result{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);align-items:center;gap:24px;min-height:clamp(250px,48vh,510px);padding:clamp(16px,3vw,34px);border:1px solid #d8b67888;border-radius:22px;background:radial-gradient(circle at 20% 50%,#c19a631e,transparent 42%),#202429}.ml-result-art{display:grid;place-items:center;min-height:250px;border-right:1px solid var(--line);position:relative}.ml-ring{width:clamp(160px,27vh,240px);height:clamp(160px,27vh,240px);border-radius:50%;display:grid;place-items:center;background:conic-gradient(var(--gold) var(--score),#454b4e 0);box-shadow:0 0 30px #c19a6333;animation:ml-ring-in .8s cubic-bezier(.2,.8,.2,1) both}.ml-ring:before{content:'';position:absolute;width:calc(clamp(160px,27vh,240px) - 28px);height:calc(clamp(160px,27vh,240px) - 28px);border-radius:50%;background:#202429}.ml-ring span{position:relative;z-index:1;text-align:center;display:grid;gap:4px}.ml-ring small{color:var(--gold);font-weight:800;letter-spacing:.1em}.ml-ring strong{font-size:clamp(50px,7vw,84px)}@keyframes ml-ring-in{from{opacity:0;transform:scale(.7) rotate(-35deg)}to{opacity:1;transform:none}}.ml-result-copy{text-align:center;display:grid;justify-items:center;gap:15px}.ml-result-copy svg{width:65px;color:var(--gold)}.ml-result-copy h2{font-size:clamp(25px,3vw,40px)}.ml-result-copy p{color:var(--muted);line-height:1.45}.ml-confetti{position:absolute;inset:0;pointer-events:none}.ml-confetti i{position:absolute;left:50%;top:50%;width:7px;height:12px;background:var(--gold);border-radius:2px;transform:rotate(var(--angle)) translateY(-125px);animation:ml-conf 3.8s ease-in-out infinite;animation-delay:var(--delay)}.ml-confetti i:nth-child(3n){background:#e4784f}@keyframes ml-conf{0%,100%{opacity:0;transform:rotate(var(--angle)) translateY(-100px)}40%,70%{opacity:1}50%{transform:rotate(var(--angle)) translateY(-150px)}}
.ml-summary-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.ml-phrase{padding:9px 12px;border:1px solid var(--line);border-radius:10px;background:#ffffff0b;animation:ml-build .5s ease both;animation-delay:var(--delay)}.ml-phrase p{font-size:clamp(12px,1.45vw,16px);font-weight:650}.ml-phrase .ml-rate{display:flex;gap:5px;margin-top:5px}.ml-phrase .ml-rate button{padding:4px 7px;border:1px solid var(--line);border-radius:7px;background:transparent;color:var(--muted);font-size:11px}.ml-phrase .ml-rate button.on{border-color:var(--gold);background:#c19a6333;color:var(--gold)}
.ml-theory{display:grid;gap:clamp(8px,1.3vh,13px)}.ml-theory-top{display:flex;align-items:center;justify-content:space-between;gap:8px}.ml-theory-controls{display:flex;gap:5px}.ml-theory-controls button{border:1px solid #d8b67888;border-radius:8px;background:#1b2024;padding:6px 9px;color:var(--gold);font-size:11px;font-weight:700}.ml-theory-rule{min-height:2.6em;color:var(--text);font-size:clamp(13px,1.5vw,17px);line-height:1.4}.ml-theory-flow{display:flex;align-items:stretch;gap:6px;min-height:78px;padding:10px;border:1px solid #d8b67880;border-radius:14px;background:linear-gradient(110deg,#30343b,#1a1e22)}.ml-theory-step{flex:1;min-width:0;display:grid;align-content:center;gap:4px;padding:7px 9px;border:1px solid #c19a6388;border-radius:10px;background:#ffffff0b;box-shadow:0 5px 12px #0003}.ml-theory-step small{color:var(--gold);font-size:10px;font-weight:800;text-transform:uppercase}.ml-theory-step strong{font-size:clamp(12px,1.5vw,18px);overflow-wrap:anywhere}.ml-theory-arrow{align-self:center;color:var(--gold);font-size:20px;font-weight:800}.ml-theory-points{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px}.ml-theory-points p{min-height:62px;padding:8px 10px;border:1px solid var(--line);border-radius:10px;background:#ffffff0b;font-size:clamp(11px,1.2vw,14px);line-height:1.35}.ml-theory-example{display:grid;gap:3px;padding:10px 12px;border-left:3px solid var(--gold);border-radius:9px;background:#c19a6324}.ml-theory-example strong{font-size:clamp(13px,1.6vw,18px)}.ml-theory-example span{color:var(--muted);font-size:clamp(11px,1.2vw,14px)}.ml-theory-hidden{visibility:hidden;opacity:0}.ml-theory-enter{animation:ml-build .6s cubic-bezier(.18,.8,.2,1) both}.ml-theory-flip{display:block;width:100%;min-height:78px;border:0;background:none;padding:0;text-align:left;perspective:800px;color:var(--text)}.ml-theory-flip-inner{position:relative;display:block;min-height:78px;transform-style:preserve-3d;transition:transform .65s cubic-bezier(.2,.8,.2,1)}.ml-theory-flip.on .ml-theory-flip-inner{transform:rotateX(180deg)}.ml-theory-face{position:absolute;inset:0;display:grid;align-content:center;gap:3px;padding:8px 12px;border:1px solid #d8b678;border-radius:11px;background:#24292d;backface-visibility:hidden;-webkit-backface-visibility:hidden}.ml-theory-face small{color:var(--gold);font-size:10px;font-weight:800;letter-spacing:.07em}.ml-theory-face strong{font-size:clamp(13px,1.5vw,18px)}.ml-theory-face.back{transform:rotateX(180deg);border-color:#68ab7e;background:#25593a}.ml-theory-face.back small{color:var(--green)}.ml-theory-face em{color:#d7e5db;font-size:11px;font-style:normal}
@media(max-width:650px){.ml-root{padding:5px;gap:5px}.ml-head{min-height:45px;padding:6px 9px}.ml-body{padding:9px;align-items:flex-start}.ml-foot{padding:5px 8px}.ml-progress{max-width:55%}.ml-progress i{width:6px}.ml-card-grid,.ml-card-grid.cols3,.ml-summary-grid{grid-template-columns:1fr 1fr}.ml-card{padding:8px;min-height:60px}.ml-stage{height:105px}.ml-truck{width:100px}.ml-result{grid-template-columns:1fr;gap:10px;padding:14px}.ml-result-art{min-height:180px;border-right:0;border-bottom:1px solid var(--line)}.ml-ring{width:150px;height:150px}.ml-ring:before{width:126px;height:126px}}
@media(max-width:650px){.ml-theory{gap:6px}.ml-theory-flow{padding:6px;gap:3px;min-height:68px}.ml-theory-step{padding:5px}.ml-theory-arrow{font-size:14px}.ml-theory-points p{padding:6px;min-height:50px}.ml-theory-flip,.ml-theory-flip-inner{min-height:70px}}
@media(max-width:420px){.ml-theory-flow{flex-direction:column}.ml-theory-arrow{align-self:center;transform:rotate(90deg)}.ml-theory-step{min-height:44px}.ml-theory-points{grid-template-columns:1fr}}
@media(max-width:420px){.ml-card-grid,.ml-card-grid.cols3,.ml-summary-grid{grid-template-columns:1fr}.ml-vocab-card,.ml-vocab-inner{min-height:72px}.ml-vocab-face{padding:7px}.ml-card{min-height:50px}.ml-option{min-height:44px}.ml-result-copy{gap:8px}}
@media(prefers-reduced-motion:reduce){.ml-root *{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}.ml-truck{left:50%}}
`;

const MODULE_CSS = "/* Module 4: emerald operations console, platinum typography and amber decisions. */\n.ml-root{--gold:#eab873;--bronze:#8cb7a8;--text:#eef4ef;--muted:#b7cbc2;--line:#90bda74d;background:radial-gradient(ellipse at 7% 0%,#2d67533b,transparent 60%),radial-gradient(ellipse at 95% 100%,#99672a22,transparent 45%),#0b1714}\n.ml-head,.ml-body{background:linear-gradient(145deg,#233b32,#13251f 62%,#1b3029);border-color:#7d9f8b66;box-shadow:0 16px 38px #0005,inset 0 1px #def6e517}.ml-head{border-radius:12px}.ml-title{color:#e8eee7}.ml-body{scrollbar-color:#8fb59f #13251f}\n.ml-progress i.on{background:linear-gradient(90deg,#80b69a,#eab873)}.ml-button.primary{background:linear-gradient(120deg,#f2cb8d,#cfa266);border-color:#eab873;color:#17251d}.ml-button.primary:hover:not(:disabled){background:#f6d8a5}\n.ml-theory-flow{background:linear-gradient(100deg,#264638,#162e26);border-color:var(--line)}.ml-theory-step{background:#203c30;border-color:#91bda857}.ml-theory-example{background:#c7dcad0c;border-left-color:#eab873}\n.ml-theory-controls button{background:#183027;border-color:var(--line);min-height:44px}.ml-theory-face{background:#243b2f;border-color:#a3bb9366}.ml-theory-face.back{background:#264737}.ml-theory-flip.on .ml-theory-flip-inner{transform:rotateY(180deg)}.ml-theory-face.back{transform:rotateY(180deg)}\n.ml-theory-flip,.ml-theory-flip-inner{min-height:112px}.ml-theory-face{overflow-wrap:anywhere}.ml-vocab-face{background:#243c31}.ml-vocab-face.back{background:#3c4430}.ml-vocab-card,.ml-vocab-inner{min-height:112px}.ml-token{background:#264136;color:#eef4ef;min-height:44px}\n.ml-slide{max-width:1120px}.ml-theory-flip-inner,.ml-vocab-inner{display:grid}.ml-theory-face,.ml-vocab-face{position:relative;inset:auto;grid-area:1/1}\n.ml-bubble{max-width:96%}.ml-bubble.right,.ml-card.reveal.open{background:#91bda816;border-color:#91bda870}.ml-option:disabled.good{opacity:1}.ml-option:hover:not(:disabled){background:#c3d6aa12}.ml-option{font-size:15px}.ml-stem{line-height:1.4}\n.ml-result{background:radial-gradient(circle at 22% 50%,#b89f6133,transparent 50%),#193026}.ml-ring:before{background:#193026}.ml-confetti i:nth-child(3n){background:#91bda8}.ml-confetti i:nth-child(3n+1){background:#eab873}.ml-phrase .ml-rate button{min-height:44px}\n.ml-slide{animation-name:m4-slide-in}.ml-theory-enter{animation-name:m4-evidence-in}.ml-bubble{animation-name:m4-evidence-in}\n@keyframes m4-slide-in{from{opacity:0;transform:translate3d(0,14px,-25px) rotateX(2deg)}to{opacity:1;transform:none}}\n@keyframes m4-evidence-in{from{opacity:0;transform:translateY(9px);filter:blur(2px)}to{opacity:1;transform:none;filter:none}}\n.m4-scene{position:relative;display:grid;grid-template-columns:180px minmax(0,1fr);align-items:center;gap:18px;padding:12px 20px 42px;min-height:176px;border:1px solid #91bda857;border-radius:14px;background:linear-gradient(#8fbc9b0a 1px,transparent 1px),linear-gradient(90deg,#8fbc9b0a 1px,transparent 1px),radial-gradient(ellipse at 20% 40%,#49795144,#0d221b);background-size:26px 26px,26px 26px,auto;overflow:hidden}\n.m4-perspective{perspective:800px;width:150px;height:112px;margin:auto}.m4-console{position:relative;width:150px;height:105px;transform-style:preserve-3d;animation:m4-console-orbit 9s ease-in-out infinite}.m4-console-screen{position:absolute;inset:0;display:grid;gap:4px;padding:10px;border:1px solid #a7ceb1;border-radius:8px;background:linear-gradient(130deg,#365848,#142b20);transform:translateZ(12px);backface-visibility:hidden;box-shadow:0 14px 20px #0005;color:#d6e4d7}.m4-console-screen span{font-size:8px;font-weight:800;letter-spacing:.08em}.m4-console-screen svg{width:128px;height:44px;color:#99cdb0}.m4-console-screen strong{font-size:11px;color:#eab873}.m4-console-side{position:absolute;right:-12px;top:0;width:24px;height:105px;transform:rotateY(90deg);background:#395b49;border:1px solid #71957c}.m4-console-floor{position:absolute;left:0;bottom:-12px;width:150px;height:24px;transform:rotateX(90deg);background:#6e805d}\n@keyframes m4-console-orbit{0%,100%{transform:rotateY(-20deg) rotateX(12deg) translateY(2px)}50%{transform:rotateY(16deg) rotateX(-5deg) translateY(-4px)}}\n.m4-signals{display:grid;gap:9px;min-width:0}.m4-tag{font-size:10px;letter-spacing:.1em;font-weight:800;color:#a9c8b3}.m4-signal-flow{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.m4-signal-flow>div{display:flex;gap:8px;align-items:center;border:1px solid #94baa53b;padding:8px;border-radius:8px;background:#29413380;animation:m4-signal 6s ease-in-out infinite;animation-delay:calc(var(--step)*2s)}.m4-signal-flow b{color:#eab873;font-size:18px}.m4-signal-flow span{font-size:10px;color:#d9e5db;font-weight:750;overflow-wrap:anywhere}.m4-signals p{font-size:11px;color:var(--muted)}\n@keyframes m4-signal{0%,32%,100%{border-color:#94baa53b;background:#29413380}12%,24%{border-color:#eab873;background:#68543166}}\n.m4-track{height:2px;background:#8eb39d44;position:relative}.m4-track i{position:absolute;top:-3px;width:26px;height:8px;border-radius:3px;background:#eab873;box-shadow:0 0 10px #eab87377;animation:m4-track 6s linear infinite}\n@keyframes m4-track{0%{left:0;opacity:0}10%,90%{opacity:1}100%{left:calc(100% - 26px);opacity:0}}\n.m4-motion{position:absolute;right:10px;bottom:6px;min-height:30px;padding:4px 9px;border:1px solid var(--line);border-radius:7px;background:#163023;color:#d1e0cf;font-size:10px!important}.m4-scene.paused *{animation-play-state:paused!important}\n.m4-hook{display:grid;gap:10px;padding:12px 16px;border-left:3px solid #eab873;background:linear-gradient(90deg,#9dc8a412,transparent);border-radius:0 12px 12px 0}.m4-hook-message{font-size:clamp(22px,2.6vw,31px);font-weight:750;color:#f0d3a7}\n.m4-document-reader{display:grid;gap:9px}.m4-tabs{display:flex;gap:8px;flex-wrap:wrap}.m4-tabs button{padding:8px 12px;min-height:44px;border:1px solid var(--line);border-radius:8px;background:#193026;color:var(--muted);font-size:12px}.m4-tabs button.on{background:#66512d55;border-color:#eab873;color:#f3d4aa}\n.m4-document{border:1px solid #91bda85c;border-radius:12px;background:#152a20;overflow:hidden;animation:m4-evidence-in .45s ease both}.m4-document header{display:grid;gap:4px;padding:10px 14px;background:#304833;border-bottom:1px solid var(--line)}.m4-document h2{font-size:20px;color:#eddbba}.m4-document dl{margin:0}.m4-document dl>div{display:grid;grid-template-columns:minmax(100px,.3fr) minmax(0,1fr);gap:10px;padding:7px 14px;border-bottom:1px solid #91bda81c}.m4-document dt{font-size:12px;color:#b5ccb5;font-weight:700}.m4-document dd{margin:0;font-size:14px;line-height:1.4;white-space:pre-line;overflow-wrap:anywhere}.m4-document-note{padding:10px 14px!important;font-size:12px;color:var(--muted)}\n.m4-source{display:grid;gap:6px;padding:12px;border:1px solid var(--line);border-radius:10px;background:#14291f}.m4-source p{font-size:15px;line-height:1.4}.m4-details{display:grid;gap:10px}.m4-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.m4-fields label{display:grid;gap:5px;font-size:13px;color:var(--muted)}.m4-fields input,.m4-written input{width:100%;min-width:0;min-height:44px;padding:9px 12px;border:1px solid #8cab97;border-radius:8px;background:#0c2017;color:var(--text);font:inherit}.m4-fields input:focus-visible,.m4-written input:focus-visible{outline:2px solid #eab873;outline-offset:2px}.m4-fields input.good{border-color:#78bc94}.m4-fields input.bad{border-color:#f2a2ac}.m4-fields small{font-size:11px;color:#f2a2ac}.m4-fields small.m4-correct{color:#9cddb5}.m4-details>.ml-button{justify-self:end}\n.m4-question-meta{display:flex;align-items:center;justify-content:space-between;gap:10px}.m4-stem{font-size:18px;line-height:1.45;font-weight:600;white-space:pre-line}.m4-written{display:grid;grid-template-columns:1fr auto;gap:8px}.m4-written label{grid-column:1/-1;font-size:13px;color:var(--muted)}\n.m4-evidence{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.m4-evidence-card{min-height:150px;padding:15px;border:1px solid var(--line);border-radius:12px;background:#1e382b;color:var(--text);text-align:left;transition:transform .35s,background .35s}.m4-evidence-card.open{background:#314a31;border-color:#b6ba80;transform:translateY(-3px)}.m4-evidence-card small{display:block;color:#eab873;font-weight:800;font-size:11px;margin-bottom:9px}.m4-evidence-card p{font-size:14px;line-height:1.5}\n@media(min-width:900px){.m4-fields{grid-template-columns:repeat(3,minmax(0,1fr))}.ml-slide[data-kind=\"mission\"] .ml-options{grid-template-columns:repeat(2,minmax(0,1fr))}.ml-slide[data-kind=\"mission\"] .m4-scene{min-height:132px;padding-block:8px 38px}.ml-slide[data-kind=\"mission\"] .m4-perspective{height:74px}.ml-slide[data-kind=\"mission\"] .m4-console{scale:.7;transform-origin:top center}}\n@media(min-width:900px) and (max-height:760px){.ml-body{padding:8px}.ml-slide{gap:8px}.ml-title{font-size:30px}.ml-theory{gap:6px}.ml-theory-rule{min-height:0;font-size:15px}.ml-theory-flow{min-height:64px;padding:6px}.ml-theory-step{padding:6px 8px}.ml-theory-step strong{font-size:16px}.ml-theory-points p{min-height:44px;padding:7px 9px}.ml-theory-example{padding:8px 10px}.ml-theory-flip,.ml-theory-flip-inner{min-height:100px}.m4-scene,.ml-slide[data-kind=\"mission\"] .m4-scene{min-height:108px;padding:6px 12px 38px;grid-template-columns:100px minmax(0,1fr)}.m4-perspective,.ml-slide[data-kind=\"mission\"] .m4-perspective{width:90px;height:60px}.m4-console,.ml-slide[data-kind=\"mission\"] .m4-console{scale:.55;transform-origin:top left}.m4-signals{gap:5px}.m4-signal-flow>div{padding:4px 6px}.m4-signal-flow b{font-size:13px}.m4-hook{padding:9px 12px;gap:7px}.m4-hook-message{font-size:24px}.m4-stem{font-size:16px}.ml-slide[data-kind=\"mission\"]{gap:6px}.ml-option{padding:7px 10px;font-size:14px}.m4-document dd{font-size:13px}.m4-document dl>div{padding:6px 12px}}\n@media(max-width:650px){.m4-scene{grid-template-columns:90px minmax(0,1fr);gap:8px;padding:10px 10px 54px;min-height:170px}.m4-perspective{width:90px;height:80px}.m4-console{scale:.58;transform-origin:left top}.m4-signal-flow{gap:4px}.m4-signal-flow>div{padding:4px;display:grid;gap:3px}.m4-signal-flow b{font-size:13px}.m4-signal-flow span{font-size:8px}.m4-motion{min-height:44px}.m4-fields,.m4-evidence{grid-template-columns:1fr}.m4-written{grid-template-columns:1fr}.m4-evidence-card{min-height:100px}.m4-document dl>div{grid-template-columns:1fr;gap:4px}.ml-theory-flip,.ml-theory-flip-inner{min-height:170px}.ml-vocab-card,.ml-vocab-inner{min-height:128px}.ml-foot{flex-wrap:wrap}.ml-note{display:none}.m4-document-reader .ml-note{display:block}.ml-progress{max-width:40%}.ml-progress i{width:4px}.m4-question-meta{flex-wrap:wrap}}\n@media(prefers-reduced-motion:reduce){.m4-console,.m4-signal-flow>div,.m4-track i{animation:none!important}.m4-console{transform:rotateY(-12deg) rotateX(8deg)}.m4-track i{left:50%}.m4-motion{display:none}.m4-document{animation:none}.m4-evidence-card{transition:none}}\n\n.ml-theory-flip{perspective:2200px}\n";

function TypeLine({ text, active = true, instant = false, speed = 24 }) {
  const [n, setN] = useState(0);
  useEffect(() => {
    if (!active) { setN(0); return; }
    if (instant || (typeof matchMedia === "function" && matchMedia("(prefers-reduced-motion: reduce)").matches)) { setN(text.length); return; }
    setN(0);
    let at = 0;
    const timer = setInterval(() => { at += 1; setN(at); if (at >= text.length) clearInterval(timer); }, speed);
    return () => clearInterval(timer);
  }, [text, active, instant, speed]);
  return <span aria-label={text}><span aria-hidden="true">{text.slice(0, n)}</span></span>;
}

function DecisionScene() {
  const [paused, setPaused] = useState(false);
  return <div className={`m4-scene ${paused ? 'paused' : ''}`}>
    <div className="m4-perspective" aria-hidden="true"><div className="m4-console">
      <div className="m4-console-floor"/><div className="m4-console-side"/>
      <div className="m4-console-screen"><span>{DATA.scene.label}</span><svg viewBox="0 0 150 66" fill="none"><path d="M10 33h35l17-21 27 42 18-21h33" stroke="currentColor" strokeWidth="3" strokeLinecap="round"/><circle cx="45" cy="33" r="5" fill="#eab873"/><circle cx="107" cy="33" r="5" fill="#eab873"/><path d="M10 60h130" stroke="currentColor" opacity=".25"/></svg><strong>{DATA.scene.ref}</strong></div>
    </div></div>
    <div className="m4-signals" aria-hidden="true"><span className="m4-tag">EVIDENCE → DECISION</span><div className="m4-signal-flow">{DATA.scene.stages.map((stage,index)=><div key={stage} style={{'--step':index}}><b>{String(index+1).padStart(2,'0')}</b><span>{stage}</span></div>)}</div><div className="m4-track"><i/></div><p>{DATA.scene.detail}</p></div>
    <button type="button" className="m4-motion" aria-pressed={paused} onClick={()=>setPaused(value=>!value)}>{paused?'Animatsiyani yoqish':'Animatsiyani to‘xtatish'}</button>
  </div>;
}

function EvidenceSlide({ slide, onReady }) {
  const [open,setOpen]=useState({});
  useEffect(()=>{if(Object.keys(open).length===3)onReady();},[open,onReady]);
  return <><p className="ml-sub">{slide.source}</p><div className="m4-evidence">{slide.items.map(([label,text],index)=><button type="button" key={label} className={`m4-evidence-card ${open[index]?'open':''}`} aria-expanded={!!open[index]} onClick={()=>setOpen(value=>({...value,[index]:true}))}><small>{label}</small><p>{open[index]?<TypeLine text={text}/>:'Dalilni ochish ↗'}</p></button>)}</div></>;
}

// Written answers keep IDs, numbers, negation, AM/PM and units meaningful.
function normalizeAnswer(value) { return String(value||'').trim().toLowerCase().replace(/[‘’]/g,"'").replace(/[.!?]+$/,'').replace(/(\D),|,(\D)/g,'$1$2').replace(/\s+/g,' '); }

function AssessmentSlide({ slide, onDone, attempt, final=false }) {
  const [index,setIndex]=useState(attempt.index||0);
  const [input,setInput]=useState(attempt.input||'');
  const [checked,setChecked]=useState(attempt.checked||null);
  const [complete,setComplete]=useState(attempt.complete||false);
  const [orders]=useState(()=>attempt.orders||(attempt.orders=slide.questions.map(q=>q.kind==='type'?[]:shuffled(q))));
  const history=useRef(attempt.history||(attempt.history={}));
  useEffect(()=>{Object.assign(attempt,{index,input,checked,complete});},[attempt,index,input,checked,complete]);
  const question=slide.questions[index];
  const written=question.kind==='type';
  const locked=!!checked&&(checked.correct||final);
  function grade(value) {
    if(locked)return;
    const correct=written?[question.answerText,...(question.accept||[])].some(answer=>normalizeAnswer(answer)===normalizeAnswer(value)):value===question.answer;
    const previous=history.current[index];
    history.current[index]={question:index+1,kind:question.kind,value,correct,firstTry:previous?previous.firstTry:correct,attempts:(previous?.attempts||0)+1,theoryRefs:question.theoryRefs};
    setChecked({value,correct});
  }
  function advance() {
    if(!checked||(!checked.correct&&!final))return;
    if(index+1<slide.questions.length){setIndex(index+1);setInput('');setChecked(null);return;}
    const answers=Object.values(history.current);
    setComplete(true);onDone({firstTry:answers.filter(answer=>answer.firstTry).length,total:slide.questions.length,answers});
  }
  if(complete)return <p className="ml-feedback good">{slide.questions.length} ta vazifa bajarildi. Birinchi urinish: {Object.values(history.current).filter(answer=>answer.firstTry).length} ta to‘g‘ri.</p>;
  return <><div className="m4-question-meta"><span className="ml-kick">{written?'YOZMA JAVOB':'QAROR'} · {index+1}/{slide.questions.length}</span>{final&&<span className="ml-note">O‘tish: {Math.ceil(slide.questions.length*DATA.threshold)}/{slide.questions.length} · birinchi urinish</span>}</div>
    {slide.kind==='mission'&&<DecisionScene/>}
    <p className="ml-lead m4-stem">{question.stem}</p>
    {written?<div className="m4-written"><label htmlFor={`answer-${index}`}>Javobingiz</label><input id={`answer-${index}`} autoComplete="off" spellCheck={false} value={input} disabled={locked} onChange={event=>{setInput(event.target.value);setChecked(null);}} onKeyDown={event=>{if(event.key==='Enter'&&input.trim())grade(input);}}/><button type="button" className="ml-button primary" disabled={locked||!input.trim()} onClick={()=>grade(input)}>Tekshirish →</button></div>:<div className="ml-options">{orders[index].map((option,position)=><button type="button" key={option.id} disabled={locked} className={`ml-option ${checked?.value===option.id?(checked.correct?'good':'bad'):''}`} onClick={()=>grade(option.id)}><i>{String.fromCharCode(65+position)}</i><span>{option.text}</span></button>)}</div>}
    {checked&&<p className={`ml-feedback ${checked.correct?'good':'bad'}`} role="status">{checked.correct?`✓ ${question.why}`:final?'Javob saqlandi. Keyingi savolga o‘ting.':written?question.hint:question.hints[checked.value]}</p>}
    <button type="button" className="ml-button primary" style={{justifySelf:'end'}} disabled={!checked||(!checked.correct&&!final)} onClick={advance}>{index+1<slide.questions.length?'Keyingi savol':'Natijani ko‘rish'} →</button>
  </>;
}

function HookSlide({ slide, onReady }) {
  useEffect(() => { onReady(); }, [onReady]);
  return <><DecisionScene/><div className="m4-hook"><span className="m4-tag">WORKPLACE CASE · O‘QUV VAZIYATI</span><p className="m4-hook-message">{slide.lines[0]}</p><p className="ml-lead">{slide.lines[1]}</p><p className="ml-sub">{slide.lines[2]}</p></div></>;
}

function DocumentSlide({ slide, onReady }) {
  const [active, setActive] = useState(0);
  const [reviewed, setReviewed] = useState({});
  const document = slide.documents[active];
  const complete = Object.keys(reviewed).length === slide.documents.length;
  useEffect(() => { if (complete) onReady(); }, [complete, onReady]);
  return <div className="m4-document-reader">
    <p className="ml-sub">{slide.instructions || "Manbani o‘qing. Har hujjatni tekshirgach belgilab chiqing; keyingi mashqlar shu detallarga asoslanadi."}</p>
    <div className="m4-tabs" role="group" aria-label="O‘quv hujjatlari">{slide.documents.map((item, index) => <button type="button" key={item.title} className={active === index ? "on" : ""} aria-pressed={active === index} onClick={() => setActive(index)}>{reviewed[index] ? "✓ " : ""}{item.title}</button>)}</div>
    <article className="m4-document" data-dense={document.rows.length > 4} key={active}><header><span className="m4-tag">SAMPLE DOCUMENT · {active + 1}/{slide.documents.length}</span><h2>{document.title}</h2></header><dl>{document.rows.map(([label, value]) => <div key={label}><dt>{label}</dt><dd>{value}</dd></div>)}</dl>{document.note && <p className="m4-document-note">{document.note}</p>}</article>
    <div className="ml-actions"><span className="ml-note" role="status">Ko‘rib chiqildi: {Object.keys(reviewed).length}/{slide.documents.length}</span><button type="button" className="ml-button primary" disabled={!!reviewed[active]} onClick={() => { setReviewed(prev => ({...prev,[active]:true})); if (active < slide.documents.length - 1) setActive(active + 1); }}>{reviewed[active] ? "Tekshirildi ✓" : "Hujjatni ko‘rib chiqdim →"}</button></div>
  </div>;
}

function DetailsSlide({ slide, onReady, onDone }) {
  const [values, setValues] = useState({});
  const [checked, setChecked] = useState(false);
  const [done, setDone] = useState(false);
  const [attempts, setAttempts] = useState(0);
  const normalize = normalizeAnswer;
  const correct = slide.fields.map(field => [field.answer, ...(field.accept || [])].some(answer => normalize(answer) === normalize(values[field.label])));
  function check(event) {
    event.preventDefault();
    if (done || slide.fields.some(field => !values[field.label]?.trim())) return;
    setChecked(true); setAttempts(value => value + 1);
    if (correct.every(Boolean)) { setDone(true); onDone?.({total:1,firstTry:attempts === 0 ? 1 : 0,attempts:attempts + 1}); onReady(); }
  }
  return <><div className="m4-source"><span className="m4-tag">MANBA · FACT CHECK</span><p>{slide.source}</p></div><div className="m4-details" role="group" aria-label="Ma’lumotlarni tekshirish" onKeyDown={event => { if (event.key === "Enter") check(event); }}>
    <div className="m4-fields">{slide.fields.map((field, index) => <label key={field.label}>{field.label}<input value={values[field.label] || ""} disabled={done} autoComplete="off" spellCheck={false} aria-invalid={checked && !correct[index]} aria-describedby={checked && !correct[index] ? `field-hint-${index}` : undefined} className={checked ? correct[index] ? "good" : "bad" : ""} onChange={event => { setChecked(false); setValues(prev => ({ ...prev, [field.label]: event.target.value })); }}/>{checked && !correct[index] && <small id={`field-hint-${index}`}>{field.hint || "Manbadagi shu detalni qayta tekshiring; raqam va vaqt birligini saqlang."}</small>}{checked && correct[index] && <small className="m4-correct">✓ Mos keldi</small>}</label>)}</div>
    {checked && <p role="status" className={`ml-feedback ${done ? "good" : "bad"}`}>{done ? "✓ Barcha detallar manbaga mos." : "Ayrim detallar mos emas. Tuzatib qayta tekshiring."}</p>}
    <button type="button" className="ml-button primary" onClick={check} disabled={done || slide.fields.some(field => !values[field.label]?.trim())}>Tekshirish →</button>
  </div></>;
}

function TheorySlide({ slide, index, onReady }) {
  const [phase, setPhase] = useState(0);
  const [run, setRun] = useState(0);
  const [skip, setSkip] = useState(false);
  const [flipped, setFlipped] = useState(false);
  const reduced = typeof matchMedia === "function" && matchMedia("(prefers-reduced-motion: reduce)").matches;
  const visible = skip || reduced ? 8 : phase;
  useEffect(() => {
    if (skip || reduced) return;
    const timers = [];
    let delay = slide.explanation.length * 18 + 250;
    for (let step = 1; step <= 3; step++) { timers.push(setTimeout(() => setPhase(step), delay)); delay += 470; }
    for (let point = 0; point < 2; point++) { timers.push(setTimeout(() => setPhase(point + 4), delay)); delay += slide.points[point].length * 14 + 180; }
    timers.push(setTimeout(() => setPhase(6), delay)); delay += slide.example.length * 18 + 200;
    timers.push(setTimeout(() => setPhase(7), delay)); delay += slide.translation.length * 18 + 220;
    timers.push(setTimeout(() => setPhase(8), delay));
    return () => timers.forEach(clearTimeout);
  }, [slide, run, skip, reduced]);
  const show = at => visible >= at ? "ml-theory-enter" : "ml-theory-hidden";
  return <div className="ml-theory">
    <div className="ml-theory-top"><span className="ml-kick">ASOSIY QOIDA · {index + 1}/{DATA.theoryCount}</span><div className="ml-theory-controls"><button type="button" onClick={() => { setPhase(0); setSkip(false); setFlipped(false); setRun(value => value + 1); }}>Qayta</button><button type="button" disabled={visible === 8} onClick={() => setSkip(true)}>Hammasi</button></div></div>
    <p className="ml-theory-rule"><TypeLine key={`rule-${run}`} text={slide.explanation} instant={skip} speed={18} /></p>
    <div className="ml-theory-flow" aria-label={visible >= 3 ? slide.steps.map(step => step[1]).join(" → ") : undefined}>{slide.steps.map(([label, value], at) => <React.Fragment key={at}>{at > 0 && <span className={`ml-theory-arrow ${show(at + 1)}`} aria-hidden={visible < at + 1}>→</span>}<div className={`ml-theory-step ${show(at + 1)}`} aria-hidden={visible < at + 1}><small>{label}</small><strong>{value}</strong></div></React.Fragment>)}</div>
    <div className="ml-theory-points">{slide.points.map((point, at) => <p key={at} className={show(at + 4)} aria-hidden={visible < at + 4}><TypeLine key={`point-${run}-${at}`} text={point} active={visible >= at + 4} instant={skip} speed={14} /></p>)}</div>
    <div className={`ml-theory-example ${show(6)}`} aria-hidden={visible < 6}><strong><TypeLine key={`example-${run}`} text={slide.example} active={visible >= 6} instant={skip} speed={18} /></strong><span><TypeLine key={`translation-${run}`} text={slide.translation} active={visible >= 7} instant={skip} speed={18} /></span></div>
    <button type="button" className={`ml-theory-flip ${show(8)} ${flipped ? "on" : ""}`} disabled={visible < 8} aria-hidden={visible < 8} aria-pressed={flipped} onClick={() => { setFlipped(true); onReady(); }}><span className="ml-theory-flip-inner"><span className="ml-theory-face"><small>XATO · TUZATISH UCHUN BOSING</small><strong>{slide.wrong}</strong></span><span className="ml-theory-face back"><small>TO‘G‘RI ✓</small><strong>{slide.right}</strong><em>{slide.why}</em></span></span></button>
  </div>;
}

function Card({ text, index, opened, onOpen }) {
  const divider = text.indexOf(":");
  const label = divider > 0 && divider < 42 ? text.slice(0, divider + 1) : "";
  const rest = label ? text.slice(divider + 1).trim() : text;
  return <button type="button" className={`ml-card reveal ${opened ? "open" : ""}`} style={{ "--delay": `${index * .11}s` }} aria-expanded={opened} onClick={onOpen}><div className="hint">{label || `QOIDA ${index + 1}`}</div><p className="hidden-copy">{opened ? <TypeLine text={rest} /> : "Ko‘rish uchun bosing ↗"}</p></button>;
}

function RevealSlide({ slide, onReady }) {
  const [seen, setSeen] = useState({});
  const cards = slide.cards || [];
  useEffect(() => { if (cards.length === 0 || Object.keys(seen).length >= cards.length) onReady(); }, [seen, cards.length, onReady]);
  return <><div className="ml-card-grid"><div className="ml-card"><div className="hint">NAZARIYA · {slide.number}</div><p className="ml-lead">{slide.heading}</p><small>Kartalarni ketma-ket ochib qoidani o‘rganing.</small></div>{cards.map((line, index) => <Card key={index} text={line} index={index} opened={!!seen[index]} onOpen={() => setSeen(prev => ({ ...prev, [index]: true }))} />)}</div></>;
}

function ChatSlide({ slide, onReady }) {
  const [translation, setTranslation] = useState(false);
  useEffect(() => { const timer = setTimeout(onReady, Math.min(1800, (slide.chat?.length || 1) * 200)); return () => clearTimeout(timer); }, [onReady, slide]);
  return <><div className="ml-chat">{slide.chat.map(([who, line], index) => <div className={`ml-bubble ${index % 2 ? "right" : ""}`} style={{ "--delay": `${index * .14}s` }} key={index}><small>{who}</small><p>{line}</p></div>)}</div>{slide.translation && <><button type="button" className="ml-button" style={{ justifySelf: "start" }} onClick={() => setTranslation(!translation)} aria-expanded={translation}>Tarjima {translation ? "−" : "+"}</button>{translation && <p className="ml-sub">{slide.translation}</p>}</>}</>;
}

function VocabSlide({ slide, onReady }) {
  const [seen, setSeen] = useState({});
  useEffect(() => { if (Object.keys(seen).length >= slide.rows.length) onReady(); }, [seen, slide.rows.length, onReady]);
  return <><p className="ml-sub">Kartalarni bosing: so‘zning ma’nosi va logistikadagi misolini ko‘ring.</p><div className="ml-card-grid cols3">{slide.rows.map(([word, meaning, example], index) => <button key={word} type="button" className={`ml-vocab-card ${seen[index] ? "open" : ""}`} style={{ animationDelay: `${index * .08}s` }} onClick={() => setSeen(prev => ({ ...prev, [index]: true }))} aria-label={`${word}: ${meaning}`} aria-pressed={!!seen[index]}><span className="ml-vocab-inner"><span className="ml-vocab-face"><small className="hint">LOGISTICS · {index + 1}</small><strong>{word}</strong><small>Bosing ↗</small></span><span className="ml-vocab-face back"><strong>{meaning}</strong><small>{example}</small></span></span></button>)}</div></>;
}

function shuffled(question) {
  const items = question.options.map((text, id) => ({ text, id }));
  for (let i = items.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [items[i], items[j]] = [items[j], items[i]];
  }
  return items;
}

function BuildSlide({ slide, onDone }) {
  const [index, setIndex] = useState(0);
  const [selected, setSelected] = useState([]);
  const [checked, setChecked] = useState(false);
  const [first, setFirst] = useState(0);
  const [attempted, setAttempted] = useState({});
  const [completed, setCompleted] = useState(false);
  const [tokenOrders] = useState(() => slide.builds.map(item => shuffled({ options: item.parts })));
  const build = slide.builds[index];
  const normalize = value => value.replace(/,/g, "").replace(/\s+([?.!])/g, "$1").replace(/[?.!]$/, "").replace(/\s+/g, " ").trim().toLowerCase();
  const assembled = selected.map(i => build.parts[i]).join(" ");
  const isRight = normalize(assembled) === normalize(build.answer);
  const check = () => {
    setChecked(true);
    if (!attempted[index]) { setAttempted(prev => ({ ...prev, [index]: true })); if (isRight) setFirst(prev => prev + 1); }
  };
  const advance = () => {
    if (index + 1 < slide.builds.length) { setIndex(index + 1); setSelected([]); setChecked(false); return; }
    setCompleted(true); onDone({ firstTry: first, total: slide.builds.length });
  };
  if (completed) return <p className="ml-feedback good">3 ta gap tuzildi. Birinchi urinishda {first} ta to‘g‘ri.</p>;
  return <><span className="ml-kick">GAP {index + 1} / {slide.builds.length}</span><p className="ml-sub">So‘zlarni to‘g‘ri tartibda birlashtiring.</p><div className="ml-token-wrap">{selected.length ? selected.map((partIndex, at) => <button type="button" key={`${partIndex}-${at}`} className="ml-token" onClick={() => { setSelected(prev => prev.filter((_, i) => i !== at)); setChecked(false); }}>{build.parts[partIndex]}</button>) : <span className="ml-dim">Gap shu yerda yig‘iladi...</span>}</div><div className="ml-token-wrap">{tokenOrders[index].map(({ text: part, id: partIndex }) => <button type="button" key={partIndex} className="ml-token" disabled={selected.includes(partIndex)} onClick={() => { setSelected(prev => [...prev, partIndex]); setChecked(false); }}>{part}</button>)}</div>{checked && <p className={`ml-feedback ${isRight ? "good" : "bad"}`} aria-live="polite">{isRight ? "✓ To‘g‘ri gap tuzildi." : "So‘z tartibini qayta ko‘ring. Fe’lning joyiga e’tibor bering."}</p>}<div className="ml-actions"><button type="button" className="ml-button" onClick={() => { setSelected([]); setChecked(false); }}>Qayta boshlash</button>{checked && isRight ? <button type="button" className="ml-button primary" onClick={advance}>Keyingi gap →</button> : <button type="button" className="ml-button primary" disabled={selected.length !== build.parts.length} onClick={check}>Tekshirish →</button>}</div></>;
}

function SummarySlide({ slide, rate, setRate }) {
  return <><p className="ml-sub">Iboralarni ovoz chiqarib o‘qing va o‘zingizni baholang. Ovoz yozilmaydi.</p><div className="ml-summary-grid">{slide.phrases.map((phrase, index) => <div className="ml-phrase" key={index} style={{ "--delay": `${index * .1}s` }}><p>{phrase}</p><div className="ml-rate">{[["hard", "Qiyin"], ["ok", "O‘rtacha"], ["easy", "Oson"]].map(([value, label]) => <button type="button" key={value} className={rate[index] === value ? "on" : ""} onClick={() => setRate(prev => ({ ...prev, [index]: value }))}>{label}</button>)}</div></div>)}</div>{slide.extras.map((extra, index) => <p className="ml-sub" key={index}>{extra}</p>)}</>;
}

function Result({ result }) {
  const passed = result.firstTry / result.total >= DATA.threshold;
  return <div className="ml-result"><div className="ml-result-art">{passed && <div className="ml-confetti" aria-hidden="true">{Array.from({ length: 16 }, (_, index) => <i key={index} style={{ "--angle": `${index * 22.5}deg`, "--delay": `${index * -.22}s` }} />)}</div>}<div className="ml-ring" style={{ "--score": `${result.firstTry / result.total * 100}%` }} role="img" aria-label={`${result.firstTry} / ${result.total}`}><span><small>NATIJA</small><strong>{result.firstTry}/{result.total}</strong></span></div></div><div className="ml-result-copy"><svg viewBox="0 0 72 64" fill="none" aria-hidden="true"><path d="M5 9c12-4 23-3 31 4 8-7 19-8 31-4v44c-12-4-23-3-31 4-8-7-19-8-31-4V9Z" fill="currentColor" opacity=".8"/><path d="M36 13v44" stroke="#30251a" strokeWidth="3"/><circle cx="57" cy="11" r="11" fill="#e8c98f"/><path d="m52 11 3 3 6-7" stroke="#20252a" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"/></svg><h2>{passed ? "Nazariy dars yakunlandi" : "Nazariyani takrorlang"}</h2><p>{passed ? DATA.code === "M4L08" ? "Yakuniy modul nazariyasi tugadi. Fakt, cheklov va dalil asosida professional muloqotni mashq qildingiz." : "Tabriklaymiz! Endi bilimni amaliy mashg‘ulotda mustahkamlang." : `O‘tish uchun kamida ${Math.ceil(result.total * DATA.threshold)} ta to‘g‘ri javob kerak. Qoidalarni qayta ko‘rib, tezkor testni takrorlang.`}</p><b className="ml-strong">{passed ? "Ajoyib, o‘tdingiz!" : "Yana urinib ko‘ring"}</b></div></div>;
}

export default function Lesson({ onFinished, onProgress }) {
  const [current, setCurrent] = useState(0);
  const [ready, setReady] = useState({});
  const [results, setResults] = useState({});
  const attempts = useRef({});
  const [rate, setRate] = useState({});
  const [finished, setFinished] = useState(false);
  const started = useRef(Date.now());
  const done = useRef(false);
  const slides = DATA.slides;
  const slide = slides[current];
  const bodyRef = useRef(null);
  useEffect(() => { if(bodyRef.current) bodyRef.current.scrollTop = 0; }, [current]);
  const rapidIndex = slides.findIndex(item => item.final);
  const rapid = results[rapidIndex];
  const resultScreen = current === rapidIndex && !!rapid;
  useEffect(() => { onProgress?.({ current: current + 1, total: slides.length }); }, [current, onProgress, slides.length]);
  const markReady = useCallback(() => setReady(prev => prev[current] ? prev : ({ ...prev, [current]: true })), [current]);
  const record = value => { setResults(prev => ({ ...prev, [current]: value })); markReady(); };
  const finish = () => {
    if (done.current || !rapid || rapid.firstTry / rapid.total < DATA.threshold) return;
    done.current = true; setFinished(true);
    const score = rapid || { firstTry: 0, total: DATA.code === "M4L08" ? 12 : 6 };
    const all = Object.values(results);
    onFinished?.({ lessonId: `${DATA.code}-learn`, lessonTitle: DATA.title, durationSec: Math.max(0, Math.round((Date.now() - started.current) / 1000)), totalQuestions: score.total, correctAnswers: score.firstTry, scorePercent: Math.round(score.firstTry / score.total * 100), passed: score.firstTry / score.total >= DATA.threshold, firstTryStats: { total: all.reduce((sum, item) => sum + item.total, 0), firstTryCorrect: all.reduce((sum, item) => sum + item.firstTry, 0) }, skillTags: DATA.skillTags, answers: Object.entries(results).map(([index, value]) => ({ slide: Number(index) + 1, ...value })), profile: { aloud: rate } });
  };
  let content;
  const props = { slide, onReady: markReady, onDone: record };
  if (slide.kind === "hook") content = <HookSlide key={current} {...props} />;
  else if (slide.kind === "document") content = <DocumentSlide key={current} {...props} />;
  else if (slide.kind === "evidence") content = <EvidenceSlide key={current} {...props} />;
  else if (slide.kind === "details") content = <DetailsSlide key={current} {...props} />;
  else if (slide.kind === "theory") content = <TheorySlide key={current} {...props} index={current - 1} />;
  else if (slide.kind === "read") content = <ChatSlide key={current} {...props} />;
  else if (slide.kind === "vocab") content = <VocabSlide key={current} {...props} />;
  else if (slide.kind === "mission" || slide.kind === "quiz") content = resultScreen ? <Result result={rapid} /> : <AssessmentSlide key={current} {...props} attempt={attempts.current[current] || (attempts.current[current] = {})} final={current === rapidIndex} />;
  else if (slide.kind === "build") content = <BuildSlide key={current} {...props} />;
  else if (slide.kind === "summary") content = <SummarySlide key={current} {...props} rate={rate} setRate={setRate} />;
  else content = <RevealSlide key={current} {...props} />;
  const failedTest = resultScreen && rapid.firstTry / rapid.total < DATA.threshold;
  const canContinue = !failedTest && (!!ready[current] || slide.kind === "summary");
  return <main className="ml-root"><style>{CSS + MODULE_CSS}</style><header className="ml-head"><span className="ml-eyebrow">M04 / OPERATIONS · {DATA.code} · {current + 1}/{slides.length}</span><span className="ml-progress" aria-hidden="true">{slides.map((_, index) => <i key={index} className={index <= current ? "on" : ""} />)}</span></header><section className="ml-body" ref={bodyRef}><div className="ml-slide" data-kind={slide.kind} key={current}><div><h1 className="ml-title"><TypeLine text={slide.heading} /></h1></div>{current === 0 && <p className="ml-sub">{DATA.goal}</p>}{content}</div></section><footer className="ml-foot"><button type="button" className="ml-button" disabled={current === 0} onClick={() => setCurrent(current - 1)}>← Orqaga</button>{!canContinue && <span className="ml-note">Davom etish uchun vazifani bajaring</span>}{failedTest && <button type="button" className="ml-button primary" onClick={() => { delete attempts.current[current]; setResults(prev => { const next = { ...prev }; delete next[current]; return next; }); setReady(prev => ({ ...prev, [current]: false })); }}>Testni qayta ishlash →</button>}{finished ? <span className="ml-feedback good">Natija saqlandi ✓</span> : current < slides.length - 1 ? <button type="button" className="ml-button primary" disabled={!canContinue} onClick={() => setCurrent(current + 1)}>{resultScreen ? "Davom etish" : "Keyingi slayd"} →</button> : <button type="button" className="ml-button primary" onClick={finish}>Darsni yakunlash →</button>}</footer></main>;
}
